/* Product component catalogue. Demos are local and do not persist or submit data. */
const productComponentTokens={version:'0.2',control:{height:{small:32,medium:40,large:48},radius:6,borderWidth:1,gap:8,paddingX:{small:14,medium:16,large:20},labelSize:14},surface:{radius:10,padding:24,gap:16},focus:{width:3,offset:3,colorRole:'text'},color:{light:{border:'#DED9E5',borderHover:'#797083',divider:'#DED9E5',surface:'#FFFFFF',background:'#FAF9F7',text:'#221F2C',muted:'#625B6E',action:'#6646D8',error:'#B93239',success:'#176B43',warning:'#885B00',info:'#255EB8'},dark:{border:'#4D465B',borderHover:'#918A9D',divider:'#4D465B',surface:'#23202C',background:'#17151D',text:'#F6F3FA',muted:'#BFB9CA',action:'#C7B5F5',error:'#FFADB0',success:'#9DDFC3',warning:'#F2CD7C',info:'#ABC9FF'}},statusSurface:{light:{neutral:{background:'#F1F1F3',border:'#E2E2E7',text:'#52525B'},success:{background:'#EAF7EE',border:'#C6E5D0',text:'#176B43'},warning:{background:'#FFF5DA',border:'#EBD69B',text:'#885B00'},error:{background:'#FDEDEE',border:'#F3CDD1',text:'#B93239'},info:{background:'#ECF3FD',border:'#CDDCF4',text:'#255EB8'}},dark:{neutral:{background:'#2D2B33',border:'#46414F',text:'#D1CCD8'},success:{background:'#193329',border:'#2E5142',text:'#9DDFC3'},warning:{background:'#3A2E18',border:'#62502D',text:'#F2CD7C'},error:{background:'#3B2228',border:'#64404A',text:'#FFADB0'},info:{background:'#202D43',border:'#3A506E',text:'#ABC9FF'}}},elevation:{flat:'none',raised:'0 2px 8px rgb(0 0 0 / 8%)',overlay:'0 8px 28px rgb(0 0 0 / 16%)',modal:'0 24px 72px rgb(0 0 0 / 24%)'},motion:{feedbackMs:180,transitionMs:280,reducedMotion:'Remove decorative loops; update states directly'}};
function pcButton(text,kind='secondary',attrs=''){return `<button type="button" class="pc-button ${kind}" ${attrs}>${text}</button>`}
function pcField(label,html,hint=''){return `<label class="pc-field"><span>${label}</span>${html}${hint?`<small>${hint}</small>`:''}</label>`}
function pcSection(id,title,description,demo,spec,usage){return `<section class="pc-section" id="pc-${id}" data-component-title="${title}"><div class="pc-section-heading"><h2>${title}</h2><p>${description}</p></div><div class="pc-demo">${demo}</div><div class="pc-spec"><code>${spec}</code><p>${usage}</p></div></section>`}
function pcLibraryShell(type,items){const form=type==='forms';return architecturalHero(form?'Form & detail':'In practice',form?'hero-form':'hero-applications')+`<div class="product-library" data-library="${type}"><section class="pc-intro"><span class="meta">${form?'Inputs & foundations':'The product component library'}</span><h2>${form?'Every field.<br>A clear next step.':'Built for the work.<br>Down to the details.'}</h2><p>${form?'Inputs, choices, validation and the surfaces that hold them. Real controls, visible states and precise rules.':'Actions, navigation, feedback, data and overlays. Explore the pieces of a creative workspace in context.'}</p><div class="pc-toolbar"><label>Control size <select data-pc-size><option value="small">Small · 32 px</option><option value="medium" selected>Medium · 40 px</option><option value="large">Large · 48 px</option></select></label><label>Preview width <select data-pc-width><option value="full">Full width</option><option value="compact">Compact · 360 px</option></select></label>${pcButton('Download component tokens','secondary','data-pc-download')}<a href="assets/component-catalogue.json" download>Component specifications · JSON</a><a href="#/${form?'applications':'foundations'}">${form?'Explore in practice':'Explore form controls'}</a></div><p class="pc-note">Interactive examples · changes stay on this page. Use the site theme toggle to inspect both modes.</p></section><div class="pc-layout"><nav class="pc-index" aria-label="Component categories">${items.map(([id,title])=>`<a href="#pc-${id}" data-pc-jump="pc-${id}">${title}</a>`).join('')}</nav><div class="pc-content">${items.map(x=>pcSection(...x)).join('')}</div></div><div class="pc-live" role="status" aria-live="polite" data-pc-live></div><dialog class="pc-dialog" data-pc-dialog aria-labelledby="pc-dialog-title"><form method="dialog"><div class="pc-dialog-top"><span class="meta">Workspace action</span><button class="pc-button icon-only" aria-label="Close dialog" value="cancel">${icon('close')}</button></div><h2 id="pc-dialog-title">Create a project</h2><p>Your designs, assets and brand explorations stay together.</p>${pcField('Project name','<input name="project" required placeholder="Untitled project">')}<div class="pc-actions"><button class="pc-button" value="cancel" formnovalidate>Cancel</button><button class="pc-button primary" value="create">Create project</button></div></form></dialog><dialog class="pc-dialog pc-drawer" data-pc-drawer aria-labelledby="pc-drawer-title"><form method="dialog"><div class="pc-dialog-top"><h2 id="pc-drawer-title">Project details</h2><button class="pc-button icon-only" aria-label="Close details" value="close">${icon('close')}</button></div><p>A side panel keeps secondary work close to its context.</p>${pcField('Name','<input value="Studio collection">')}${pcField('Status','<select><option>Draft</option><option>In review</option><option>Ready</option></select>')}<button class="pc-button primary" value="save">Save details</button></form></dialog></div>`+next(form?'foundations':'applications')}
function productForms(){const input=(type,value='',extra='')=>`<input type="${type}" ${value?`value="${value}"`:''} ${extra}>`;return pcLibraryShell('forms',[
['text','Text inputs','Labels stay visible. Hints explain the expected format before an error occurs.',`<div class="pc-grid three">${pcField('Project name',input('text','','placeholder="Enter a name"'),'Default · name your project')}${pcField('Workspace URL','<div class="pc-input-group"><span>design.os/</span><input aria-label="Workspace slug" value="studio"></div>','Prefix · context is separate from the value')}${pcField('Search assets','<div class="pc-input-group">'+icon('search')+'<input type="search" aria-label="Search assets" placeholder="Search by name"></div>','Search · use the native clear control')}</div><div class="pc-grid three">${pcField('Email',input('email','','placeholder="you@studio.com"'),'Email keyboard and native validation')}${pcField('Password','<div class="pc-input-group"><input type="password" value="CreativeStudio42" aria-label="Example password"><button type="button" data-pc-password aria-label="Show password">Show</button></div>','Use a reveal action; never truncate passwords')}${pcField('Website',input('url','','placeholder="https://example.com"'),'URL · include the scheme')}</div>`,`control.height 32 / 40 / 48 · radius 6 · border 1 subtle · padding-x 14 · gap 8`,'Subtle neutral boundaries match the surrounding containers; hover and focus strengthen the field outline. The focus indicator uses the text color, with a 3 px offset ring; brand violet is reserved for actions and selected values.'],
['field-states','Field states','Default, hover, focus, filled, invalid, read-only and disabled.',`<div class="pc-grid three">${pcField('Default',input('text','','placeholder="Project name"'))}${pcField('Focus specimen',input('text','A new idea','class="pc-focus-specimen"'),'Static illustration of keyboard focus')}${pcField('Filled',input('text','Studio collection'))}${pcField('Invalid name',input('text','','aria-invalid="true" aria-describedby="pc-name-error" placeholder="Required"')+'<small id="pc-name-error" class="pc-error">'+icon('close')+' Enter a project name.</small>')}${pcField('Read-only',input('text','Project DS-014','readonly'),'Readable and selectable')}${pcField('Disabled',input('text','Unavailable','disabled'),'Explain why the control is unavailable')}</div>`,`border default: color.border · hover: color.borderHover · invalid: color.error · focus: text / 3 px`,'Errors use text and an icon as well as color. Disabled controls do not accept interaction; read-only values can still be copied.'],
['long-text','Text areas & number controls','Long prompts need room. Numeric values need clear limits and units.',`<div class="pc-grid two">${pcField('Creative brief','<textarea rows="4" maxlength="240" data-pc-count placeholder="Describe what you want to create…"></textarea><small data-pc-counter>0 / 240</small>','Resize vertically; preserve the reading width')}${pcField('Variations','<input type="number" min="1" max="12" value="3">','1–12 outputs per request')}${pcField('Budget','<div class="pc-input-group"><span>$</span><input aria-label="Budget in dollars" type="number" min="0" step="0.01" value="50"></div>','Units are always visible')}</div>`,`textarea min-height 112 · number min 1 / max 12 · label 14 / 500 · body 16`,'Keep length limits visible. Use numeric controls for quantities, never account numbers or identifiers.'],
['select','Selects, dropdowns & multi-select','Use a select for a single value and a checkbox group for multiple selections.',`<div class="pc-grid two">${pcField('Output format','<select><option>PNG image</option><option>SVG vector</option><option>PDF document</option><option>WebP image</option></select>','Native select · keyboard and type-ahead supported')}${pcField('Project template','<input list="pc-templates" placeholder="Search or choose a template"><datalist id="pc-templates"><option value="Brand identity"><option value="Landing page"><option value="Product dashboard"><option value="Campaign artwork"></datalist>','Searchable suggestion field · custom values accepted')}<fieldset><legend>Export assets</legend>${['Images','Typography','Color tokens','Icons'].map((v,i)=>`<label class="pc-choice"><input type="checkbox" ${i<2?'checked':''}>${v}</label>`).join('')}</fieldset><div><span class="pc-label">Open menu specimen</span><div class="pc-menu pc-menu-specimen"><strong>Output format</strong><span class="selected">${icon('check')} PNG image</span><span>SVG vector</span><span>PDF document</span></div></div></div>`,`menu radius 10 · option min-height 40 · padding 8 · elevation overlay · neutral border`,'Keep menu width aligned with its trigger. Use visible selection marks. The open specimen documents layout; native controls above provide the interactive examples.'],
['choices','Checkboxes, radios & switches','Different selection rules deserve different controls.',`<div class="pc-grid three"><fieldset><legend>Include in export</legend><label class="pc-choice"><input type="checkbox" checked>Source files</label><label class="pc-choice"><input type="checkbox">Preview images</label><label class="pc-choice"><input type="checkbox" disabled>Team-only files</label></fieldset><fieldset><legend>Project visibility</legend><label class="pc-choice"><input type="radio" name="visibility" checked>Private</label><label class="pc-choice"><input type="radio" name="visibility">Workspace</label><label class="pc-choice"><input type="radio" name="visibility" disabled>Public (unavailable)</label></fieldset><fieldset><legend>Preferences</legend><label class="pc-choice"><input class="pc-switch" type="checkbox" role="switch" checked>Autosave</label><label class="pc-choice"><input class="pc-switch" type="checkbox" role="switch">Email updates</label><label class="pc-choice"><input class="pc-switch" type="checkbox" role="switch" disabled>Managed setting</label></fieldset></div>`,`checkbox / radio 18 · target min 44 · switch 36 × 22 · label-gap 10`,'Checkboxes allow multiple values; radios allow one per group. Switches apply immediately. Group related options with a fieldset and legend.'],
['pickers','Date, time, range & color pickers','Use familiar native pickers with explicit labels and an always-visible value.',`<div class="pc-grid three">${pcField('Start date','<input type="date" value="2026-11-27">','Native calendar · follows the browser locale')}${pcField('Review time','<input type="time" value="14:30">','Local workspace time')}${pcField('Accent color','<input type="color" value="#6646d8" data-pc-color><output data-pc-color-value>#6646D8</output>','Artwork only · does not recolor dashboard chrome')}${pcField('Image quality','<input type="range" min="10" max="100" value="80" data-pc-range><output>80%</output>','Range 10–100 · step 1')}${pcField('Date range','<div class="pc-date-range"><input type="date" aria-label="Range start" value="2026-11-27"><span>to</span><input type="date" aria-label="Range end" value="2026-12-04"></div>','Two native dates · validate end is after start')}</div><div class="pc-calendar-spec"><div><span class="pc-label">Calendar specimen</span><p class="pc-muted">November 2026 · select a day to update the example date.</p><div class="pc-calendar" role="group" aria-label="November 2026 date selection"><strong>November 2026</strong><div class="pc-calendar-grid">${['Su','Mo','Tu','We','Th','Fr','Sa'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:30},(_,i)=>`<button type="button" data-pc-day="${i+1}" aria-label="November ${i+1}, 2026" aria-pressed="${i===26}">${i+1}</button>`).join('')}</div></div><p class="pc-muted" data-pc-date-status>Selected: November 27, 2026</p></div></div>`,`date / time: control.height · calendar cell 36 · range target 44 · color swatch 40 × 40 · gap 8`,'The browser supplies the calendar and clock UI. Format dates for the viewer and store unambiguous values. Do not use color alone to name a selection.'],
['upload','Upload & attachment states','A file input, selected-file feedback and a visible removal action.',`<label class="pc-upload">${icon('image')}<strong>Choose reference files</strong><span>PNG, JPEG, WebP or SVG · up to 10 MB each</span><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" multiple data-pc-files></label><div data-pc-file-list class="pc-file-list" aria-live="polite">No files selected.</div>`,`drop zone min-height 160 · radius 10 · border 1 dashed · neutral surface`,'This demo reads file names and sizes locally; it does not upload files. Validate type and size again on the server in a real product.'],
['validation','A complete form','Submit to see field-level errors and a success state. Nothing is sent.',`<form class="pc-example-form" data-pc-form novalidate><div class="pc-grid two">${pcField('Project name *','<input name="name" required maxlength="80" aria-describedby="pc-form-name-hint"><small id="pc-form-name-hint">Use a name your team will recognize.</small>')}${pcField('Owner email *','<input name="email" type="email" required aria-describedby="pc-form-email-hint"><small id="pc-form-email-hint">Used for project notifications.</small>')}${pcField('Format','<select name="format"><option>Design project</option><option>Brand exploration</option><option>Image collection</option></select>')}${pcField('Notes','<textarea name="notes" rows="2" placeholder="Optional context"></textarea>')}</div><div class="pc-form-message" role="status"></div><div class="pc-actions"><button type="reset" class="pc-button">Reset</button><button type="submit" class="pc-button primary">Create project</button></div></form>`,`form field-gap 24 · label-gap 8 · section-gap 32 · required marker explained`,'Validate on submit, keep entered values, focus the first invalid control and associate each error with its field. Success is announced without losing context.'],
['foundations','Containers, borders & spacing','The same quiet foundation supports every form.',`<div class="pc-grid three"><div class="pc-foundation"><span>Control</span><div class="pc-radius-demo r6">6 px</div><code>radius.control</code></div><div class="pc-foundation"><span>Card</span><div class="pc-radius-demo r10">10 px</div><code>radius.card</code></div><div class="pc-foundation"><span>Panel</span><div class="pc-radius-demo r16">16 px</div><code>radius.panel</code></div></div><div class="pc-spacing">${[4,8,12,16,24,32,48,64].map(n=>`<div><i style="width:${n}px"></i><code>${n}</code></div>`).join('')}</div><div class="pc-border-examples"><span>1 px · decorative divider</span><span>1 px · control boundary</span><span>3 px · keyboard focus</span></div>`,`space 4 / 8 / 12 / 16 / 24 / 32 / 48 / 64 · container padding 24 · control border 1`,'Use dividers for grouping and subtle neutral resting borders for controls, with stronger hover and focus treatment. Do not tint input borders or shadows violet just to make them feel branded.']])}
function productPractice(){return pcLibraryShell('practice',[
['buttons','Buttons & action hierarchy','One primary action per decision area. Explore sizes with the control above.',`<div class="pc-stack"><div class="pc-actions">${pcButton('Create project','primary','data-pc-notify="Project created (demo)."')}${pcButton('Save draft','secondary','data-pc-notify="Draft saved (demo)."')}${pcButton('View details','tertiary','data-pc-open-drawer')}${pcButton('Delete project','danger','data-pc-notify="Destructive actions require confirmation in a real workflow."')}${pcButton('Unavailable','secondary','disabled')}</div><div class="pc-actions">${pcButton(icon('plus')+' New project','primary','data-pc-open-dialog')}${pcButton(icon('download')+' Export','secondary','data-pc-notify="Export prepared (demo)."')}${pcButton('Continue <span aria-hidden="true">→</span>','secondary','data-pc-notify="Next step (demo)."')}${pcButton('←','icon-only','aria-label="Previous item" data-pc-notify="Previous item"')}${pcButton('→','icon-only','aria-label="Next item" data-pc-notify="Next item"')}${pcButton(icon('heart'),'icon-only','aria-label="Favorite project" aria-pressed="false" data-pc-favorite')}${pcButton('<i class="pc-spinner"></i> Saving','primary','disabled aria-label="Saving, please wait"')}</div><div class="pc-actions"><button class="pc-button primary pc-travel" data-pc-notify="Primary action selected.">Create with AI</button><span class="pc-muted">Subtle light pass on hover · primary action only</span></div></div>`,`height 32 / 40 / 48 · padding-x 14 / 16 / 20 · radius 6 · icon 20 · gap 8`,'Primary uses the action token. Secondary uses neutral borders, tertiary uses text. Destructive red is reserved for destructive intent. The traveling light is optional decoration, disabled for reduced motion.'],
['button-states','Action states','Compare state treatments without relying only on color.',`<div class="pc-state-strip">${[['Default',''],['Hover','pc-hover-specimen'],['Focus','pc-focus-specimen'],['Pressed','pc-pressed-specimen']].map(([label,cls])=>`<div><span>${label}</span><button class="pc-button primary ${cls}" data-pc-notify="${label} specimen">Create project</button></div>`).join('')}<div><span>Disabled</span>${pcButton('Create project','primary','disabled')}</div><div><span>Loading</span>${pcButton('<i class="pc-spinner"></i> Creating','primary','disabled')}</div></div>`,`hover: neutral overlay · pressed: inset shadow · focus: 3 px text-color ring / 3 px offset`,'Loading preserves button width and explains the task. Disabled controls have a documented reason in the surrounding UI. Never remove keyboard focus styling.'],
['menus','Dropdown menus & popovers','Actions sit in menus. Supplementary explanations sit in popovers.',`<div class="pc-actions"><details class="pc-dropdown"><summary class="pc-button">Project actions <span aria-hidden="true">⌄</span></summary><div class="pc-menu">${['Rename','Duplicate','Move to folder','Archive'].map(t=>`<button type="button" data-pc-menu-action="${t}">${t}</button>`).join('')}</div></details><details class="pc-dropdown"><summary class="pc-button">Export options <span aria-hidden="true">⌄</span></summary><div class="pc-menu">${['PNG image','SVG vector','PDF document'].map(t=>`<button type="button" data-pc-menu-action="${t}">${t}</button>`).join('')}</div></details><button class="pc-button" popovertarget="pc-explain">About credits</button><div popover id="pc-explain" class="pc-popover"><strong>Generation credits</strong><p>Credits are used when you generate a new artifact. Review the estimate before starting.</p><button class="pc-button" popovertarget="pc-explain" popovertargetaction="hide">Got it</button></div></div><p class="pc-muted">Menu examples use disclosure buttons and native buttons; Tab navigates the options. Escape closes the disclosure.</p>`,`trigger min-height 40 · menu min-width 200 · option min-height 40 · elevation overlay`,'Use a native select for values and a menu for actions. Keep menus inside the viewport. Popovers dismiss with Escape or an outside click.'],
['navigation','Navigation, tabs & breadcrumbs','Make location and the active destination visible.',`<nav class="pc-breadcrumb" aria-label="Example breadcrumb"><a href="#" data-pc-notify="Workspace navigation (demo)">Workspace</a><span>/</span><a href="#" data-pc-notify="Projects navigation (demo)">Projects</a><span>/</span><span aria-current="page">Studio collection</span></nav><div class="pc-tabs" role="tablist" aria-label="Project views">${['Overview','Assets','Activity'].map((v,i)=>`<button role="tab" id="pc-tab-${i}" aria-controls="pc-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${v}</button>`).join('')}</div>${['Your project overview. Keep the next action clear.','12 assets in your project. Use filters to find what you need.','No new activity. Updates will appear here.'].map((v,i)=>`<div class="pc-tab-panel" role="tabpanel" id="pc-panel-${i}" aria-labelledby="pc-tab-${i}" ${i?'hidden':''}>${v}</div>`).join('')}<div class="pc-segments" role="group" aria-label="Asset view">${['Grid','List','Compact'].map((v,i)=>`<button aria-pressed="${i===0}" data-pc-segment>${v}</button>`).join('')}</div>`,`tabs height 44 · active underline 2 · breadcrumb gap 8 · segment radius 6`,'Tabs switch panels in the same context. Breadcrumbs show hierarchy. Segmented buttons change a local view. Arrow keys move between tabs.'],
['notifications','Toasts & inline notifications','Feedback names the outcome and gives a next step when needed.',`<div class="pc-actions">${['success','error','warning','info'].map(t=>pcButton('Show '+t,'secondary',`data-pc-toast="${t}"`)).join('')}</div><div class="pc-grid two">${[['success','check','Changes saved','Your latest edits are saved.'],['error','close','Couldn’t save','Your draft is still here. Try again.'],['warning','clock','Review before publishing','Two assets need descriptive names.'],['info','chat','A new version is ready','Review the changes before using it.']].map(([t,i,h,p])=>`<div class="pc-alert ${t}">${icon(i)}<div><strong>${h}</strong><p>${p}</p></div></div>`).join('')}</div>`,`toast width min(380 px, viewport − 32 px) · padding 16 · radius 14 · icon badge 32 / glyph 18`,'Status uses a compact icon, clear content and a uniform subtle outline, without an accent stripe. Toasts are dismissible and remain until dismissed in this demo. Keep critical errors inline and do not rely on transient feedback.'],
['overlays','Modal dialogs & side panels','Use a modal for a focused decision, a drawer for contextual details.',`<div class="pc-overlay-spec"><div class="pc-mini-modal"><span class="meta">Dialog anatomy</span><h3>Create a project</h3><p>A clear title, one short explanation and a deliberate action area.</p><div class="pc-actions">${pcButton('Cancel','secondary','data-pc-notify="Cancel action specimen"')}${pcButton('Create project','primary','data-pc-open-dialog')}</div></div></div><div class="pc-actions">${pcButton('Open dialog','primary','data-pc-open-dialog')}${pcButton('Open side panel','secondary','data-pc-open-drawer')}</div>`,`dialog width min(480 px, viewport − 32 px) · padding 24 · radius 16 · elevation modal`,'Native dialog provides modal focus containment and Escape dismissal. Return focus to the trigger on close. Keep destructive confirmation specific to the action.'],
['data','Tables, sorting, filters & pagination','Dense information still needs a readable rhythm.',`<div class="pc-table-tools">${pcField('Find a project','<input type="search" data-pc-table-search placeholder="Filter by project name">')}${pcField('Status','<select data-pc-table-filter><option value="all">All statuses</option><option>Draft</option><option>Ready</option><option>In review</option></select>')}</div><div class="pc-table-wrap"><table class="pc-table"><thead><tr><th scope="col"><input type="checkbox" aria-label="Select all visible projects" data-pc-select-all></th><th scope="col"><button data-pc-sort aria-label="Sort projects by name">Project <span aria-hidden="true">↕</span></button></th><th scope="col">Status</th><th scope="col">Assets</th><th scope="col">Owner</th></tr></thead><tbody data-pc-tbody></tbody></table></div><div class="pc-table-bottom"><span data-pc-table-info></span><div class="pc-actions">${pcButton('Previous','secondary','data-pc-page="-1"')}${pcButton('Next','secondary','data-pc-page="1"')}</div></div>`,`row min-height 56 · cell padding 12 / 16 · header 14 / 600 · divider 1 · 3 rows per demo page`,'Sort controls expose their direction. Filters reset pagination. Selection applies to the visible page; checkbox names identify their rows. Empty results are explicit.'],
['status','Tags, avatars & progress','Soft tinted fills distinguish semantic statuses; neutral tags stay gray.',`<div class="pc-actions"><span class="pc-tag">Draft</span><span class="pc-tag success">${icon('check')} Ready</span><span class="pc-tag warning">In review</span><span class="pc-tag error">Needs attention</span><span class="pc-tag">Brand <button aria-label="Remove Brand filter" data-pc-remove-tag>×</button></span><span class="pc-avatar" role="img" aria-label="Alex Morgan">AM</span><span class="pc-avatar secondary-avatar" role="img" aria-label="Maya Chen">MC</span><span class="pc-avatar" role="img" aria-label="Three more collaborators">+3</span></div><div class="pc-grid two"><div><label for="pc-progress">Uploading references · <output data-pc-progress-label>60%</output></label><progress id="pc-progress" value="60" max="100">60%</progress>${pcButton('Advance example','secondary','data-pc-progress')}</div><div class="pc-loading"> <i class="pc-spinner"></i><span>Generating preview…</span></div></div><ol class="pc-steps"><li class="done">${icon('check')} Brief</li><li aria-current="step">2 · Generate</li><li>3 · Review</li></ol>`,`tag height 28 · tinted fill / subtle semantic border · avatar 32 · progress height 6 · steps gap 24 · spinner 18`,'Show percentages only for measured progress. Indeterminate loading uses a spinner and a task label. Never imply a generated estimate is actual progress.'],
['states','Empty, loading, error & success states','Explain what happened and what someone can do next.',`<div class="pc-grid two"><div class="pc-state-panel">${icon('folder')}<h3>No projects yet</h3><p>Create a project to bring your ideas together.</p>${pcButton('Create project','primary','data-pc-open-dialog')}</div><div class="pc-state-panel"><div class="pc-skeleton" aria-hidden="true"><i></i><i></i><i></i></div><span role="status">Loading project details…</span></div><div class="pc-state-panel"><span class="pc-error">${icon('close')}</span><h3>Couldn’t load assets</h3><p>Your work is safe. Check your connection and try again.</p>${pcButton('Try again','secondary','data-pc-retry')}</div><div class="pc-state-panel">${icon('check')}<h3>Your export is ready</h3><p>Review your files before sharing them.</p>${pcButton('Review export','secondary','data-pc-notify="Export preview opened (demo)."')}</div></div>`,`state padding 32 · icon 40 · heading 20 / 650 · text max-width 32 ch · action gap 16`,'A zero state, no search results, permission issue and network failure need different copy. Skeletons match the expected content shape; reduced motion removes shimmer.'],
['disclosure','Cards, accordions, tooltips & shortcuts','Progressive disclosure keeps secondary information close.',`<div class="pc-grid two"><article class="pc-product-card"><div class="pc-card-art">Aa</div><div><span class="pc-tag">Brand exploration</span><h3>Studio collection</h3><p>12 assets · Edited today</p>${pcButton('Open project','secondary','data-pc-open-drawer')}</div></article><div><details class="pc-accordion" open><summary>Project settings</summary><p>Use accordions for secondary settings that benefit from grouping.</p></details><details class="pc-accordion"><summary>Export settings</summary><p>Keep frequently used actions visible. Do not hide critical errors in closed panels.</p></details><div class="pc-tooltip-wrap"><button class="pc-button icon-only" aria-label="Export project" aria-describedby="pc-export-tip">${icon('download')}</button><span class="pc-tooltip" id="pc-export-tip" role="tooltip">Export project</span></div><span class="pc-muted">Shortcut label <kbd>⌘</kbd> <kbd>K</kbd></span></div></div>`,`card radius 10 · content padding 24 · accordion target 44 · tooltip 12 / 16 · shadow overlay`,'Tooltips appear on hover and keyboard focus; they must not contain essential instructions. Accordions use native disclosure behavior. Shortcut labels supplement a visible action.'],
['elevation','Elevation, borders & layers','Depth comes from neutral shadows and clear surface roles.',`<div class="pc-grid four">${[['Flat','none','No elevation'],['Raised','0 2px 8px rgb(0 0 0 / 8%)','Cards that need separation'],['Overlay','0 8px 28px rgb(0 0 0 / 16%)','Menus and popovers'],['Modal','0 24px 72px rgb(0 0 0 / 24%)','Focused dialogs']].map(([n,shadow,use])=>`<div class="pc-elevation" style="box-shadow:${shadow}"><strong>${n}</strong><span>${use}</span><code>${shadow}</code></div>`).join('')}</div><div class="pc-layer-scale"><span>Base · 0</span><span>Sticky · 10</span><span>Menu · 20</span><span>Modal · top layer</span><span>Toast · 100</span></div>`,`shadow color neutral black · decorative border color.divider · field border color.border`,'In dark mode, surface contrast and borders carry more of the separation. Never use colored glow as the default elevation. Native dialogs and popovers use the browser top layer.'],
['layout','Layout & spacing in context','A small workspace composition brings the components together.',`<div class="pc-workspace"><aside><strong>DesignOS</strong><span class="active">${icon('grid')} Home</span><span>${icon('folder')} Projects</span><span>${icon('image')} Assets</span></aside><div><div class="pc-workspace-top"><div><span class="meta">Workspace</span><h3>Good things take shape.</h3></div>${pcButton('New project','primary','data-pc-open-dialog')}</div><div class="pc-grid two"><div class="pc-stat"><span>Projects</span><strong>12</strong></div><div class="pc-stat"><span>Ready to review</span><strong>3</strong></div></div><div class="pc-alert info">${icon('chat')}<div><strong>Your next direction is ready</strong><p>Review the latest exploration with your team.</p></div></div></div></div>`,`shell gap 24 · sidebar 160 · content padding 24 · page heading 24 / 700 · section-gap 32`,'Keep most surfaces neutral, use violet for the primary action and selected states, and use semantic colors only when the information has that meaning.']])}
function bindProductLibrary(root){const lib=root.querySelector('.product-library');if(!lib)return()=>{};const cleanups=[],timers=[];const on=(el,event,fn)=>{el.addEventListener(event,fn);cleanups.push(()=>el.removeEventListener(event,fn))};const live=lib.querySelector('[data-pc-live]');function announce(message){live.textContent=message;timers.push(setTimeout(()=>{if(live.textContent===message)live.textContent=''},4000))}function showToast(type,message){live.replaceChildren();const toast=document.createElement('div');toast.className='pc-toast '+type;toast.innerHTML=`${icon({success:'check',error:'close',warning:'clock',info:'chat'}[type]||'check')}<div class="pc-toast-content"><strong>${({success:'Changes saved',error:'Something needs attention',warning:'Review needed',info:'Workspace update'})[type]||'Workspace update'}</strong><span></span></div><button type="button" aria-label="Dismiss notification">${icon('close')}</button>`;toast.querySelector('.pc-toast-content span').textContent=message;toast.querySelector('button').onclick=()=>toast.remove();live.append(toast)}
 on(lib.querySelector('[data-pc-size]'),'change',e=>{lib.dataset.controlSize=e.target.value;announce('Control size: '+e.target.selectedOptions[0].textContent)});on(lib.querySelector('[data-pc-width]'),'change',e=>{lib.dataset.previewWidth=e.target.value});
 lib.querySelectorAll('[data-pc-jump]').forEach(a=>on(a,'click',e=>{e.preventDefault();document.getElementById(a.dataset.pcJump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}));
 on(lib.querySelector('[data-pc-download]'),'click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(productComponentTokens,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='designos-component-tokens.json';a.click();timers.push(setTimeout(()=>URL.revokeObjectURL(url),1000))});
 lib.querySelectorAll('[data-pc-password]').forEach(b=>on(b,'click',()=>{const input=b.previousElementSibling,show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password')}));
 lib.querySelectorAll('[data-pc-count]').forEach(t=>on(t,'input',()=>t.parentElement.querySelector('[data-pc-counter]').textContent=t.value.length+' / 240'));
 lib.querySelectorAll('[data-pc-range]').forEach(t=>on(t,'input',()=>t.nextElementSibling.textContent=t.value+'%'));
 lib.querySelectorAll('[data-pc-day]').forEach(b=>on(b,'click',()=>{lib.querySelectorAll('[data-pc-day]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const value='2026-11-'+b.dataset.pcDay.padStart(2,'0');lib.querySelector('#pc-pickers input[type=date]').value=value;lib.querySelector('[data-pc-date-status]').textContent='Selected: November '+b.dataset.pcDay+', 2026'}));const dateRange=lib.querySelector('.pc-date-range');if(dateRange){const [start,end]=dateRange.querySelectorAll('input');const update=()=>{end.min=start.value;const bad=Boolean(end.value&&start.value&&end.value<start.value);end.setCustomValidity(bad?'End date must be on or after the start date.':'');end.setAttribute('aria-invalid',String(bad));let msg=dateRange.querySelector('.pc-error');if(!msg){msg=document.createElement('small');msg.className='pc-error';msg.id='pc-range-error';dateRange.append(msg);end.setAttribute('aria-describedby',msg.id)}msg.textContent=bad?'End date must be on or after the start date.':''};on(start,'change',update);on(end,'change',update)}const color=lib.querySelector('[data-pc-color]');if(color)on(color,'input',()=>lib.querySelector('[data-pc-color-value]').textContent=color.value.toUpperCase());
 const file=lib.querySelector('[data-pc-files]');if(file)on(file,'change',()=>{const list=lib.querySelector('[data-pc-file-list]');list.replaceChildren();[...file.files].forEach(f=>{const row=document.createElement('div');const typeOK=/\.(png|jpe?g|webp|svg)$/i.test(f.name),valid=typeOK&&f.size<=10*1024*1024;row.className='pc-file-row'+(valid?'':' pc-error');const text=document.createElement('span');text.textContent=f.name+' · '+(f.size/1024).toFixed(0)+' KB'+(valid?'':' · '+(!typeOK?'Unsupported type':'Exceeds 10 MB'));const remove=document.createElement('button');remove.type='button';remove.className='pc-button';remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+f.name);remove.onclick=()=>{row.remove();if(!list.children.length){list.textContent='No files selected.';file.value=''}};row.append(text,remove);list.append(row)});if(!file.files.length)list.textContent='No files selected.'});
 const form=lib.querySelector('[data-pc-form]');if(form){on(form,'submit',e=>{e.preventDefault();let first;form.querySelectorAll('.pc-validation-error').forEach(n=>n.remove());form.querySelectorAll('input').forEach(input=>{input.removeAttribute('aria-invalid');input.setAttribute('aria-describedby','pc-form-'+input.name+'-hint');if(!input.checkValidity()){input.setAttribute('aria-invalid','true');const err=document.createElement('small');err.className='pc-validation-error pc-error';err.id='pc-validation-'+input.name;err.textContent=input.name==='name'?'Enter a project name.':'Enter a valid email address.';input.after(err);input.setAttribute('aria-describedby','pc-form-'+input.name+'-hint '+err.id);first??=input}});const message=form.querySelector('.pc-form-message');if(first){message.textContent='Review the highlighted fields.';first.focus()}else{message.textContent='Project created. This example is local; no data was submitted.';showToast('success','Project created (demo).')}});on(form,'reset',()=>{form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.querySelectorAll('.pc-validation-error').forEach(el=>el.remove());form.querySelector('.pc-form-message').textContent=''})}
 const dialog=lib.querySelector('[data-pc-dialog]'),drawer=lib.querySelector('[data-pc-drawer]');lib.querySelectorAll('[data-pc-open-dialog]').forEach(b=>on(b,'click',()=>dialog.showModal()));lib.querySelectorAll('[data-pc-open-drawer]').forEach(b=>on(b,'click',()=>drawer.showModal()));on(dialog,'close',()=>{if(dialog.returnValue==='create')showToast('success','Project created (demo).')});on(drawer,'close',()=>{if(drawer.returnValue==='save')showToast('success','Details saved (demo).')});
 lib.querySelectorAll('[data-pc-notify]').forEach(b=>on(b,'click',e=>{e.preventDefault();showToast('info',b.dataset.pcNotify)}));lib.querySelectorAll('[data-pc-toast]').forEach(b=>on(b,'click',()=>showToast(b.dataset.pcToast,{success:'Changes saved. Your latest edits are safe.',error:'Couldn’t save. Your draft is still here. Try again.',warning:'Review needed. Two assets need descriptive names.',info:'A new version is available to review.'}[b.dataset.pcToast])));
 lib.querySelectorAll('[data-pc-favorite]').forEach(b=>on(b,'click',()=>{const selected=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(selected));b.setAttribute('aria-label',selected?'Unfavorite project':'Favorite project');announce(selected?'Added to favorites':'Removed from favorites')}));
 lib.querySelectorAll('[data-pc-menu-action]').forEach(b=>on(b,'click',()=>{b.closest('details').open=false;showToast('info',b.dataset.pcMenuAction+' selected (demo).')}));lib.querySelectorAll('.pc-dropdown').forEach(d=>on(d,'keydown',e=>{if(e.key==='Escape'){d.open=false;d.querySelector('summary').focus()}}));
 const tabs=[...lib.querySelectorAll('[role=tab]')];function activateTab(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;lib.querySelector('#'+t.getAttribute('aria-controls')).hidden=!selected})}tabs.forEach((tab,i)=>{on(tab,'click',()=>activateTab(tab));on(tab,'keydown',e=>{let next;if(e.key==='ArrowRight')next=tabs[(i+1)%tabs.length];if(e.key==='ArrowLeft')next=tabs[(i+tabs.length-1)%tabs.length];if(e.key==='Home')next=tabs[0];if(e.key==='End')next=tabs.at(-1);if(next){e.preventDefault();activateTab(next);next.focus()}})});
 lib.querySelectorAll('[data-pc-segment]').forEach(b=>on(b,'click',()=>{lib.querySelectorAll('[data-pc-segment]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));announce(b.textContent+' view selected (demo).')}));
 lib.querySelectorAll('[data-pc-remove-tag]').forEach(b=>on(b,'click',()=>{b.parentElement.remove();announce('Brand filter removed')}));const progress=lib.querySelector('#pc-progress');if(progress)on(lib.querySelector('[data-pc-progress]'),'click',()=>{progress.value=progress.value>=100?0:Math.min(100,progress.value+20);lib.querySelector('[data-pc-progress-label]').textContent=progress.value+'%'});
 lib.querySelectorAll('[data-pc-retry]').forEach(b=>on(b,'click',()=>{const panel=b.closest('.pc-state-panel');panel.querySelector('h3').textContent='Assets loaded';panel.querySelector('p').textContent='The connection is restored. You can continue.';b.disabled=true;b.textContent='Loaded';announce('Assets loaded (demo).')}));
 const tbody=lib.querySelector('[data-pc-tbody]');if(tbody){const projects=[['Brand exploration','Draft',12,'Alex'],['Campaign artwork','Ready',8,'Maya'],['Dashboard concepts','In review',6,'Alex'],['Image collection','Ready',24,'Sam'],['Launch direction','Draft',9,'Maya'],['Studio collection','In review',12,'Sam'],['Website refresh','Ready',16,'Alex']];let page=0,asc=true;const selected=new Set(),search=lib.querySelector('[data-pc-table-search]'),filter=lib.querySelector('[data-pc-table-filter]'),all=lib.querySelector('[data-pc-select-all]');function rows(){return projects.filter(r=>r[0].toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='all'||r[1]===filter.value)).sort((a,b)=>asc?a[0].localeCompare(b[0]):b[0].localeCompare(a[0]))}function draw(){const data=rows();page=Math.max(0,Math.min(page,Math.ceil(data.length/3)-1));const visible=data.slice(page*3,page*3+3);tbody.innerHTML=visible.length?visible.map(([n,s,c,o])=>`<tr><td><input type="checkbox" aria-label="Select ${n}" data-project="${n}" ${selected.has(n)?'checked':''}></td><th scope="row">${n}</th><td><span class="pc-tag ${s==='Ready'?'success':s==='In review'?'warning':''}">${s}</span></td><td>${c}</td><td>${o}</td></tr>`).join(''):'<tr><td colspan="5">No projects match these filters.</td></tr>';lib.querySelector('[data-pc-table-info]').textContent=`${data.length? page*3+1:0}–${Math.min(page*3+3,data.length)} of ${data.length} · ${selected.size} selected`;lib.querySelector('[data-pc-page="-1"]').disabled=page===0;lib.querySelector('[data-pc-page="1"]').disabled=(page+1)*3>=data.length;all.checked=visible.length>0&&visible.every(r=>selected.has(r[0]));all.indeterminate=visible.some(r=>selected.has(r[0]))&&!all.checked;lib.querySelector('[data-pc-sort]').closest('th').setAttribute('aria-sort',asc?'ascending':'descending')};on(search,'input',()=>{page=0;draw()});on(filter,'change',()=>{page=0;draw()});on(lib.querySelector('[data-pc-sort]'),'click',()=>{asc=!asc;draw()});lib.querySelectorAll('[data-pc-page]').forEach(b=>on(b,'click',()=>{page+=Number(b.dataset.pcPage);draw()}));on(tbody,'change',e=>{if(e.target.dataset.project){e.target.checked?selected.add(e.target.dataset.project):selected.delete(e.target.dataset.project);draw()}});on(all,'change',()=>{rows().slice(page*3,page*3+3).forEach(r=>all.checked?selected.add(r[0]):selected.delete(r[0]));draw()});draw()}
 return()=>{cleanups.forEach(f=>f());timers.forEach(clearTimeout);[dialog,drawer].forEach(d=>{if(d.open)d.close()})}
}
